    beginShape(); for(let x=0;x<=W;x+=W/20){ vertex(x, y+Math.sin(x*0.01+t*0.6+i)*14+Math.sin(x*0.03+t)*6);} endShape(); }
  dc.restore(); blendMode(BLEND); }
