if(P.shafts>0.05){ dc.save(); blendMode(SCREEN);
  const ns=Math.floor(3+P.shafts*5); for(let i=0;i<ns;i++){ const sx=W*(i+0.5+Math.sin(t*0.2+i)*0.15)/ns; const sw=W*0.06*(0.6+fr(i));
