  fill(Cc([h,70,90], 70)); push(); translate(fxp,fyp); scale(spd>0?1:-1,1); ellipse(0,0,fsz*2,fsz); triangle(-fsz,0,-fsz*1.7,-fsz*0.5,-fsz*1.7,fsz*0.5); pop(); } }
// bubbles
noStroke(); for(let i=0;i<20;i++){ const life=(t*0.2+fr(i))%1; const bx=fr(i+9)*W; const by=H-life*H; fill(Cc([P.hue,20,100],(1-life)*22)); circle(bx+Math.sin(t+i)*8, by, 2+fr(i)*4); }
// sandy floor
fill(Cc(sandc,100)); beginShape(); vertex(0,H); vertex(0,floorY); for(let x=0;x<=W;x+=W/14){ vertex(x, floorY + Math.sin(x*0.01+2)*10 - fr(x)*6);} vertex(W,floorY); vertex(W,H); endShape(CLOSE);
